// Parse Error Details
// Requirements: 12.1, 12.2, 12.4

const error = $json.error;
const workflow = $json.workflow;
const execution = $json.execution;

// Classify error
function classifyError(errorMessage) {
  const messageLower = (errorMessage || '').toLowerCase();

  if (messageLower.includes('invalid_dimension_score') || 
      messageLower.includes('parsing_incomplete') || 
      messageLower.includes('no_jd_available')) {
    return { errorCode: messageLower.split(':')[0].trim().toUpperCase().replace(/\s+/g, '_') || 'PROCESSING_ERROR', isRetryable: false, shouldNotify: true };
  }

  if (messageLower.includes('openai') || messageLower.includes('timeout') || messageLower.includes('network')) {
    return { errorCode: 'API_ERROR', isRetryable: true, shouldNotify: true };
  }

  if (messageLower.includes('db_') || messageLower.includes('database') || messageLower.includes('postgres')) {
    return { errorCode: 'DB_ERROR', isRetryable: true, shouldNotify: true };
  }

  if (messageLower.includes('redis')) {
    return { errorCode: 'REDIS_ERROR', isRetryable: true, shouldNotify: true };
  }

  return { errorCode: 'UNKNOWN_ERROR', isRetryable: false, shouldNotify: true };
}

const errorMessage = error?.message || error?.description || JSON.stringify(error);
const classification = classifyError(errorMessage);

return [{
  json: {
    errorMessage,
    errorCode: classification.errorCode,
    isRetryable: classification.isRetryable,
    shouldNotify: classification.shouldNotify,
    workflowId: workflow?.id,
    workflowName: workflow?.name,
    executionId: execution?.id,
    executionMode: execution?.mode,
    nodeName: $json.node?.name || 'unknown',
    timestamp: new Date().toISOString()
  }
}];
